// tools/assistant.js - Thesis / Paper Assistant: a cited introduction, literature review or research-gap analysis
// assembled from about 50 relevant abstracts (OpenAlex), optionally following the citation network of up to three key
// papers. Every sentence is taken from a source abstract and links back to it; nothing is generated by an AI model.
// This is a rapid draft from abstracts, not a systematic (PRISMA) review.
const S = require('../sources');
const ST = require('../styles');
const M = require('./match');
const { relevanceScores, cleanDoi } = require('../text');

const enc = encodeURIComponent;
const short = id => String(id || '').replace('https://openalex.org/', '');
const SELECT = 'id,doi,title,publication_year,authorships,primary_location,biblio,abstract_inverted_index,is_retracted,type,cited_by_count,topics,ids,keywords';

const BACKGROUND = /\b(is (?:a|an|one of)|are (?:a|an|among)|has been|have been|remains?|important|major|common|leading|prevalen|worldwide|global|widely|increasingly|burden|plays? a)\b/i;
const FINDING = /\b(show(?:ed|s|n)?|found|reveal(?:ed|s)?|demonstrat(?:ed|es)|indicat(?:ed|es)|result(?:ed|s) in|significantly|increas(?:ed|es)|decreas(?:ed|es)|reduc(?:ed|es)|improv(?:ed|es)|associated|exhibit(?:ed|s)|inhibit(?:ed|s)|was (?:higher|lower|effective)|were (?:higher|lower|effective))\b/i;
const GAP = /\b(however|limited|remains? (?:unclear|unknown|poorly)|unknown|lack(?:s|ing)?|few (?:studies|data|reports)|further (?:research|studies|investigation|work)|need(?:ed|s)? (?:to|for)|warrant|gap|not (?:yet )?been|poorly understood|inconsistent|controvers|conflicting|scarce|insufficient)\b/i;
const METHOD = /\b(?:was|were) (?:done|performed|carried out|conducted|collected|analy[sz]ed|determined|measured|evaluated|assessed|used|prepared|extracted|tested|screened|retrieved|presented)\b|^(?:a total of|using|by using)\b/i;
const AIM = /^(?:the )?(?:aim|objective|purpose|goal)s? of|^this (?:study|paper|work|review) (?:aim|investigat|evaluat|examin|assess|explor)|^we (?:aimed|investigated|evaluated|examined|assessed|conducted|performed|enrolled|recruited)|^(?:methods?|materials and methods|design|setting|participants)\s*:/i;

function rewrite(s) {
  let t = String(s).trim()
    .replace(/^(?:background|results?|findings|conclusions?|objectives?|introduction)\s*:\s*/i, '')
    .replace(/^(?:in (?:this|the present|our) (?:study|work|paper|review|trial|analysis),?\s*|here,?\s*|herein,?\s*|overall,?\s*|taken together,?\s*)/i, '')
    .replace(/^(?:we|the authors?)\s+(?:found|showed|demonstrated|observed|report(?:ed)?|confirmed|conclude[d]?)\s+that\s+/i, '')
    .replace(/^(?:(?:our|these|the|this study's)\s+)?(?:results|findings|data)\s+(?:of this study\s+)?(?:have\s+|has\s+)?(?:show(?:ed|n)?|indicate[sd]?|suggest(?:ed)?|demonstrate[sd]?|reveal(?:ed)?|confirm(?:ed)?)\s+that\s+/i, '')
    .replace(/^(?:this|the present) (?:study|review) (?:shows?|showed|suggests?|demonstrates?) that\s+/i, '')
    .replace(/\bour\b/g, 'their').replace(/\bOur\b/g, 'Their').replace(/\bwe\b/g, 'the authors').replace(/\bWe\b/g, 'The authors')
    .replace(/[.\s]+$/, '');
  return t.charAt(0).toUpperCase() + t.slice(1);
}

function lowerFirst(t) { return /^[A-Z][a-z]/.test(t) ? t.charAt(0).toLowerCase() + t.slice(1) : t; }

const CONNECT = ['', 'Similarly, ', 'In addition, ', 'Furthermore, ', 'Likewise, ', 'Moreover, '];

async function fetchWorks(path) {
  const r = await S.openalex(path);
  if (!r.ok) {
    if (r.status === 429) throw new Error('OpenAlex daily limit reached — add an OPENALEX_API_KEY.');
    return [];
  }
  return r.data.results || [];
}

/** Resolve a key paper given as DOI or title */
async function resolveKeyPaper(q) {
  const doi = cleanDoi(q);
  if (doi) {
    const r = await S.openalex(`works/doi:${enc(doi)}?select=${SELECT},referenced_works`);
    return r.ok ? r.data : null;
  }
  const list = await fetchWorks(`works?search=${enc(String(q).slice(0, 300))}&per-page=1&select=${SELECT},referenced_works`);
  return list[0] || null;
}

function toWork(w) {
  const rec = S.fromOpenAlex(w);
  return { ...rec, id: short(w.id), type: w.type, citedBy: w.cited_by_count || 0, topic: w.topics?.[0]?.display_name || null, subfield: w.topics?.[0]?.subfield?.display_name || null };
}

/** Sentences of an abstract with their role */
function classify(abstract) {
  const sents = M.sentenceSpans(abstract).map(x => x.text).filter(x => x.length > 40 && x.length < 600);
  return sents.map((s, i) => ({
    text: s,
    role: AIM.test(s) || (METHOD.test(s) && !FINDING.test(s.replace(METHOD, ''))) ? 'aim' : GAP.test(s) ? 'gap' : FINDING.test(s) ? 'finding' : (i < 2 && BACKGROUND.test(s)) || BACKGROUND.test(s) ? 'background' : 'other'
  }));
}

/**
 * input: { topic, draftType: 'article'|'thesis', section: 'introduction'|'review'|'gap', yearFrom, yearTo, keyPapers: [], focus, style }
 */
async function runAssistant(input, update = () => {}) {
  const topic = String(input.topic || '').trim();
  if (topic.length < 4) throw new Error('Enter a topic or a few keywords.');
  const section = ['introduction', 'review', 'gap'].includes(input.section) ? input.section : 'introduction';
  const thesis = input.draftType === 'thesis';
  const style = ST.styleKey(input.style || 'apa7');
  const filters = ['has_abstract:true', 'is_retracted:false', 'type:article|review'];
  if (input.yearFrom) filters.push(`from_publication_date:${parseInt(input.yearFrom, 10)}-01-01`);
  if (input.yearTo) filters.push(`to_publication_date:${parseInt(input.yearTo, 10)}-12-31`);
  const q = enc(topic.slice(0, 300));

  update('Searching for relevant publications', 8);
  const [relevant, cited] = await Promise.all([
    fetchWorks(`works?search=${q}&filter=${filters.join(',')}&per-page=60&select=${SELECT}`),
    fetchWorks(`works?search=${q}&filter=${filters.join(',')}&sort=cited_by_count:desc&per-page=15&select=${SELECT}`)
  ]);
  const pool = new Map();
  for (const w of [...relevant, ...cited]) if (w.title && w.abstract_inverted_index) pool.set(short(w.id), w);

  // Citation network of the key papers: their references and the works citing them
  const keyPapers = [];
  for (const kp of (input.keyPapers || []).filter(Boolean).slice(0, 3)) {
    update(`Following the citation network of "${String(kp).slice(0, 40)}"`, 20 + keyPapers.length * 8);
    const w = await resolveKeyPaper(kp).catch(() => null);
    if (!w) continue;
    keyPapers.push({ id: short(w.id), title: w.title, year: w.publication_year, doi: cleanDoi(w.doi) });
    if (w.abstract_inverted_index) pool.set(short(w.id), w);
    const refs = (w.referenced_works || []).map(short).slice(0, 40);
    const [refWorks, citing] = await Promise.all([
      refs.length ? fetchWorks(`works?filter=openalex:${refs.join('|')},has_abstract:true&per-page=50&select=${SELECT}`) : [],
      fetchWorks(`works?filter=cites:${short(w.id)},has_abstract:true,is_retracted:false&sort=cited_by_count:desc&per-page=20&select=${SELECT}`)
    ]);
    for (const x of [...refWorks, ...citing]) if (x.title && x.abstract_inverted_index) pool.set(short(x.id), x);
  }
  if (pool.size < 5) throw new Error('Too few publications with abstracts were found. Try broader keywords or remove the year filter.');

  update(`Reading ${pool.size} abstracts`, 50);
  let works = [...pool.values()].map(toWork);
  const rel = relevanceScores(`${topic} ${topic} ${input.focus || ''}`, works.map(w => `${w.title} ${w.abstract}`));
  works.forEach((w, i) => { w.rel = rel[i] + (keyPapers.some(k => k.id === w.id) ? 0.5 : 0); });
  works = works.sort((a, b) => b.rel - a.rel).slice(0, 50);
  works.forEach(w => { w.sentences = classify(w.abstract); });

  // Sub-topics from OpenAlex topic labels
  const topicCount = new Map();
  for (const w of works) if (w.topic) topicCount.set(w.topic, (topicCount.get(w.topic) || 0) + 1);
  const subtopics = [...topicCount.entries()].filter(([, n]) => n >= 3).sort((a, b) => b[1] - a[1]).slice(0, thesis ? 5 : 3).map(([t]) => t);
  if (!subtopics.length) subtopics.push(null);

  const used = new Set(); // "workId|sentence" already placed
  const take = (w, role) => {
    const s = w.sentences.find(x => x.role === role && !used.has(`${w.id}|${x.text}`));
    if (!s) return null;
    used.add(`${w.id}|${s.text}`);
    return { text: rewrite(s.text), cites: [w.id], basis: s.text };
  };
  const byCited = [...works].sort((a, b) => (b.type === 'review') - (a.type === 'review') || b.citedBy - a.citedBy);
  const sectionsOut = [];

  const findingsFor = (sub, n) => {
    const out = [];
    const list = works.filter(w => !sub || w.topic === sub).sort((a, b) => b.rel - a.rel);
    for (const w of list) {
      if (out.length >= n) break;
      const s = take(w, 'finding');
      if (s) out.push(s);
    }
    return section === 'review' ? out.sort((a, b) => (works.find(w => w.id === a.cites[0]).year || 0) - (works.find(w => w.id === b.cites[0]).year || 0)) : out;
  };
  const dedupeOpeners = list => list.map((s, i) => (i && /^however,\s*/i.test(s.text) && /^however,/i.test(list[i - 1].text) ? { ...s, text: s.text.replace(/^however,\s*/i, '').replace(/^./, c => c.toUpperCase()) } : s));
  const connect = list => list.map((s, i) => (i && CONNECT[i % CONNECT.length] ? { ...s, text: CONNECT[i % CONNECT.length] + lowerFirst(s.text) } : s));

  if (section === 'introduction') {
    const bg = [];
    for (const w of byCited) { if (bg.length >= (thesis ? 4 : 2)) break; const s = take(w, 'background'); if (s) bg.push(s); }
    const paras = [{ sentences: bg }];
    for (const sub of subtopics) paras.push({ sentences: connect(findingsFor(sub, thesis ? 4 : 3)) });
    const gaps = [];
    for (const w of byCited) { if (gaps.length >= (thesis ? 3 : 2)) break; const s = take(w, 'gap'); if (s) gaps.push(s); }
    const closing = input.focus ? [{ text: `The present ${thesis ? 'thesis' : 'study'} therefore addresses the following: ${lowerFirst(String(input.focus).trim().replace(/[.\s]+$/, ''))}`, cites: [], own: true }] : [];
    paras.push({ sentences: [...dedupeOpeners(gaps), ...closing] });
    sectionsOut.push({ heading: thesis ? 'Chapter 1 — Introduction' : 'Introduction', paragraphs: paras.filter(p => p.sentences.length) });
  }

  if (section === 'review') {
    const subsections = subtopics.map(sub => ({ heading: sub || topic, paragraphs: [{ sentences: connect(findingsFor(sub, thesis ? 7 : 5)) }] }));
    sectionsOut.push({ heading: thesis ? 'Chapter 2 — Literature Review' : 'Literature Review', paragraphs: [], subsections: subsections.filter(s => s.paragraphs[0].sentences.length) });
  }

  let analysis = null;
  if (section === 'gap') {
    update('Analysing publication trends and sub-topics', 70);
    const now = new Date().getFullYear();
    const trendR = await S.openalex(`works?search=${q}&filter=from_publication_date:${now - 11}-01-01,type:article|review&group_by=publication_year`);
    const trend = (trendR.ok ? trendR.data.group_by || [] : []).map(g => ({ year: parseInt(g.key, 10), works: g.count })).filter(g => g.year < now + 1).sort((a, b) => a.year - b.year);
    const topicsR = await S.openalex(`works?search=${q}&filter=from_publication_date:${now - 6}-01-01,type:article|review&group_by=topics.id`);
    const topicGroups = (topicsR.ok ? topicsR.data.group_by || [] : []).slice(0, 10).map(g => ({ id: short(g.key), name: g.key_display_name, works: g.count }));
    // Growth of each sub-topic: last 3 years vs the 3 before
    const dataGaps = [];
    for (const t of topicGroups.slice(0, 8)) {
      const g = await S.openalex(`works?search=${q}&filter=topics.id:${t.id},from_publication_date:${now - 6}-01-01&group_by=publication_year`);
      const ys = Object.fromEntries((g.ok ? g.data.group_by || [] : []).map(x => [parseInt(x.key, 10), x.count]));
      const recent = [now - 1, now - 2, now - 3].reduce((a, y) => a + (ys[y] || 0), 0);
      const before = [now - 4, now - 5, now - 6].reduce((a, y) => a + (ys[y] || 0), 0);
      t.growth = before ? Math.round((recent - before) / before * 100) : null;
    }
    // Share of the whole literature on the topic over the same six years
    const total = trend.filter(t => t.year >= now - 6).reduce((a, t) => a + t.works, 0) || topicGroups.reduce((a, t) => a + t.works, 0) || 1;
    for (const t of topicGroups) {
      t.share = Math.round(t.works / total * 100);
      if (t.share <= 10 && (t.growth ?? 0) > 30) dataGaps.push({ text: `${t.name}: a smaller but fast-growing strand (${t.works.toLocaleString()} papers, about ${t.share}% of this literature; +${t.growth}% in the last three years) — room for new contributions`, cites: [], label: 'from data' });
      else if ((t.growth ?? 0) < -25) dataGaps.push({ text: `${t.name}: attention is declining (${t.growth}% over three years) — earlier questions may have been left open`, cites: [], label: 'from data' });
    }
    const reviewGaps = [], inferred = [];
    for (const w of byCited) {
      const s = take(w, 'gap');
      if (!s) continue;
      if (w.type === 'review' && reviewGaps.length < 6) reviewGaps.push({ ...s, label: 'from review' });
      else if (inferred.length < 6) inferred.push({ ...s, label: 'inferred' });
    }
    const first = trend[0], last = trend.filter(t => t.year < now).pop();
    analysis = {
      trend, topics: topicGroups,
      trendSummary: first && last ? `Publications on this topic went from ${first.works.toLocaleString()} in ${first.year} to ${last.works.toLocaleString()} in ${last.year}` : null,
      gaps: [...reviewGaps, ...dataGaps, ...inferred]
    };
    sectionsOut.push({
      heading: 'Research-gap analysis',
      paragraphs: [
        ...(analysis.trendSummary ? [{ sentences: [{ text: analysis.trendSummary, cites: [], own: true }] }] : []),
        { sentences: analysis.gaps.map(g => ({ text: g.text, cites: g.cites || [], basis: g.basis || null, label: g.label })) }
      ]
    });
  }

  // Number / label citations in order of first use, build the reference list
  const order = [];
  const walk = secs => secs.forEach(s => { (s.paragraphs || []).forEach(p => p.sentences.forEach(x => (x.cites || []).forEach(c => { if (!order.includes(c)) order.push(c); }))); if (s.subsections) walk(s.subsections); });
  walk(sectionsOut);
  const byId = new Map(works.map(w => [w.id, w]));
  const items = order.map((id, i) => ({ record: byId.get(id), firstCited: i, id }));
  const bib = ST.orderBibliography(items, style);
  const number = new Map(bib.map((b, i) => [b.id, i + 1]));
  const label = ids => (ids.length ? ST.toText(ST.inText(style, { nums: ids.map(id => number.get(id)), records: ids.map(id => byId.get(id)) })) : '');
  const render = secs => secs.map(s => ({
    ...s,
    paragraphs: (s.paragraphs || []).map(p => ({ sentences: p.sentences.map(x => ({ ...x, citeLabel: label(x.cites || []), display: `${x.text}${x.cites?.length ? ' ' + label(x.cites) : ''}.` })) })),
    subsections: s.subsections ? render(s.subsections) : undefined
  }));
  const sections = render(sectionsOut);
  return {
    kind: 'assistant', topic, section, draftType: thesis ? 'thesis' : 'article', style, focus: input.focus || '', keyPapers,
    sections, analysis,
    references: bib.map((b, i) => { const e = ST.entry(b.record, style); return { id: b.id, number: i + 1, text: ST.toText(e), html: ST.toHtml(e), doi: b.record.doi }; }),
    sources: works.filter(w => order.includes(w.id)).map(w => ({ id: w.id, title: w.title, year: w.year, journal: w.journal, doi: w.doi, abstract: w.abstract, type: w.type })),
    screened: pool.size,
    disclaimer: 'A rapid draft assembled from publication abstracts, not a systematic (PRISMA) review. Every sentence comes from the cited abstract — read the sources, rewrite in your own words and verify the references before use.'
  };
}

module.exports = { runAssistant, rewrite, classify };
